#include <iiGUI/iiGUI.h>
#include <algorithm>
#include <iostream>
#include <stdexcept>
using namespace ii;
namespace {
void check(bool v,const char* m){if(!v)throw std::runtime_error(m);}
template<class T>T take(core::Result<T> r){if(!r)throw std::runtime_error(r.error().message);return std::move(*r);}
void good(core::Result<void> r){if(!r){if(r.error().cause)std::rethrow_exception(r.error().cause);throw std::runtime_error(r.error().message);}}
void key(gui::WidgetMount m,gui::WidgetKey k,bool shift=false){good(m.dispatch_input({.kind=gui::WidgetInputKind::key_down,.key=k,.shift=shift}));}
void click(gui::WidgetMount m,gui::Rect r){const auto x=r.x+r.width/2,y=r.y+r.height/2;good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_down,.x=x,.y=y}));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_up,.x=x,.y=y}));}
void lifecycle(){
    gui::Host host;gui::Widget popup,anchor,input,slider,button;int opened=0,closed=0,clicked=0,submits=0;std::string text;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{
        auto root=take(w.vstack({},"root"));anchor=take(w.button(root,"anchor",{.text="Open"}));popup=take(w.popover(root,"popup",{}, {.opened=[&]{++opened;},.closed=[&]{++closed;}}));auto content=take(w.vstack(popup,"content"));
        input=take(w.input_field(content,"input",{.commit_on_focus_loss=true},[&](std::string v){text=std::move(v);},[&]{++submits;}));slider=take(w.slider(content,"slider",{.value=.5,.step=.1,.width=180}));button=take(w.button(content,"button",{.text="Action"},[&]{++clicked;}));return {};}));
        check(!take(popup.snapshot()).visible&&!take(input.snapshot()).visible,"Closed popover content exposed");good(anchor.focus());good(popup.open_at(40,80));check(opened==1&&take(input.snapshot()).focused&&take(popup.snapshot()).opened,"Popover did not open/focus existing content");
        good(m.dispatch_input({.kind=gui::WidgetInputKind::text,.text="native"}));check(text=="native","Popover swallowed text");key(m,gui::WidgetKey::tab);check(submits==1&&take(slider.snapshot()).focused,"Tab did not commit/focus inside content");key(m,gui::WidgetKey::right);check(take(slider.snapshot()).value>.59,"Popover swallowed slider keys");key(m,gui::WidgetKey::tab);good(button.activate());check(clicked==1&&take(popup.snapshot()).opened,"Content action unexpectedly closed popup");
        key(m,gui::WidgetKey::tab);check(take(input.snapshot()).focused,"Tab escaped popover focus scope");good(popup.close_popup());check(closed==1&&take(anchor.snapshot()).focused&&!take(input.snapshot()).visible&&submits==2,"Close did not commit/hide/restore focus");good(popup.open_at(50,90));check(take(input.snapshot()).text=="native","Reopening recreated content");good(host.request_close());}}));check(!popup.open_at(0,0),"Closed generation reopened");
}
void policies(){
    gui::Host host;gui::Widget popup,modal,anchor,field,content;int clicks=0,escaped=0;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.absolute_stack({},"root",{500,400}));anchor=take(w.button(root,"anchor",{.text="Outside"},[&]{++clicks;}));good(anchor.set_frame({10,10,100,24}));
        popup=take(w.popover(root,"popup",{.width=220,.height=120}));content=take(w.vstack(popup,"content"));field=take(w.input_field(content,"field",{}));modal=take(w.popover(root,"modal",{.width=200,.height=100,.modal=true,.dim=true}));auto child=take(w.vstack(modal,"modalContent"));(void)take(w.button(child,"modalAction",{.text="Action"}));return {};}));
        good(anchor.focus());good(popup.open_at(200,150));check(!take(anchor.snapshot()).input_blocked,"Nonmodal popover blocked underlying controls");click(m,take(anchor.snapshot()).bounds);check(clicks==1&&!take(popup.snapshot()).opened,"Nonmodal outside press did not dismiss and reach target");
        good(modal.open_at(200,150));check(take(anchor.snapshot()).input_blocked&&take(modal.snapshot()).modal&&take(modal.snapshot()).dim,"Modal policy not exposed/enforced");click(m,take(anchor.snapshot()).bounds);check(clicks==1&&!take(modal.snapshot()).opened,"Modal outside press leaked to target");
        good(popup.open_at(200,150));good(content.set_escape_action([&]{++escaped;}));key(m,gui::WidgetKey::escape);check(escaped==1&&take(popup.snapshot()).opened,"Popover bypassed content Escape handler");good(content.set_escape_action({}));key(m,gui::WidgetKey::escape);check(!take(popup.snapshot()).opened,"Unhandled Escape did not close popover");good(popup.open_at(200,150));auto outside=take(anchor.snapshot()).bounds;good(m.dispatch_input({.kind=gui::WidgetInputKind::context_request,.x=outside.x+2,.y=outside.y+2}));check(!take(popup.snapshot()).opened,"Outside secondary press did not dismiss popover");good(host.request_close());}}));
}
void placement(){
    gui::Host host({.size={640,480}});gui::Widget popup,anchor,last,slider;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.vstack({},"root"));anchor=take(w.button(root,"anchor",{.text="Anchor"}));popup=take(w.popover(root,"popup",{.width=220,.height=120,.clip_content=true}));auto content=take(w.vstack(popup,"content",{.spacing=8}));slider=take(w.slider(content,"slider",{.width=180}));for(int i=0;i<12;++i)last=take(w.button(content,"item"+std::to_string(i),{.text="Row"}));return {};}));
        auto implicit=take(popup.snapshot()).implicit_size;check(implicit==gui::Size{220,120},"Closed popup implicit size unavailable");good(popup.open_at(630,470));auto r=take(popup.snapshot()).bounds;check(r.x>=8&&r.y>=8&&r.x+r.width<=632&&r.y+r.height<=472,"Popover escaped viewport margins");
        good(last.focus());check(take(popup.snapshot()).scroll_offset>0&&take(last.snapshot()).visible,"Offscreen focused content was not revealed");good(popup.close_popup());good(popup.open_for(anchor,0,30));const auto first=take(popup.snapshot()).bounds;good(host.set_content_size({800,500}));const auto moved=take(popup.snapshot()).bounds;check(moved.x!=first.x,"Anchored popover did not follow reflow on resize");
        good(popup.close_popup());good(popup.open_at(100,100));good(slider.focus());auto s=take(slider.snapshot()).bounds;good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_down,.x=s.x+s.width/2,.y=s.y+s.height/2}));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_move,.x=900,.y=600}));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_up,.x=900,.y=600}));check(take(popup.snapshot()).opened&&take(slider.snapshot()).value==1,"Captured slider drag was dismissed on outside release");good(host.request_close());}}));
}
void nesting(){
    gui::Host host;gui::Widget popup,menu,input,anchor,item;int picked=0;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.vstack({},"root"));popup=take(w.popover(root,"popup"));auto content=take(w.vstack(popup,"content"));input=take(w.input_field(content,"field"));anchor=take(w.button(content,"anchor",{.text="Menu"}));menu=take(w.menu(anchor,"menu"));item=take(w.menu_item(menu,"item",{.label="Pick",.has_child_items=false},[&]{++picked;}));return {};}));
        good(popup.open_at(60,60));good(anchor.focus());good(menu.open_for(anchor,30,0));check(take(input.snapshot()).input_blocked&&take(item.snapshot()).focused,"Nested menu did not own input focus");key(m,gui::WidgetKey::escape);check(take(popup.snapshot()).opened&&!take(menu.snapshot()).opened&&take(anchor.snapshot()).focused,"Nested menu close did not restore parent focus");good(input.focus());good(m.dispatch_input({.kind=gui::WidgetInputKind::text,.text="still alive"}));check(take(input.snapshot()).text=="still alive","Parent content did not resume after menu");good(menu.open_for(anchor,30,0));good(popup.close_popup());check(!take(menu.snapshot()).opened&&!take(input.snapshot()).visible&&picked==0,"Parent close left descendant popup active");good(host.request_close());}}));
}
void rendering(){
    gui::Host host({.size={400,300}});auto model=std::make_shared<gui::ColorPickerModel>();good(model->edit_hsv(0,1,1));gui::Widget popup,field;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.vstack({},"root"));(void)take(w.label(root,"behind",{.text="UNDERLYING TEXT"}));popup=take(w.popover(root,"popup",{.width=180,.height=180,.clip_content=true}));auto content=take(w.vstack(popup,"content",{.spacing=0}));field=take(w.color_surface(content,"field",{.model=model,.field=gui::ColorField::saturation_brightness,.width=128,.height=128}));(void)take(w.label(content,"inside",{.text="Inside"}));return {};}));
        good(popup.open_at(30,30));auto image=take(host.capture_canvas());const auto r=take(field.snapshot()).bounds;const auto scale=take(host.snapshot()).backing_scale;const auto at=(std::size_t((r.y+64)*scale)*image.width+std::size_t((r.x+64)*scale))*4;
        check(image.rgba[at]>110&&image.rgba[at]<145&&image.rgba[at+1]>45&&image.rgba[at+1]<85,"Popover did not paint its native color domain above the backdrop");check(take(host.graphics_info()).api==gui::GraphicsApi::metal,"Native popup rendering did not reach Metal");good(popup.close_popup());auto after=take(host.capture_canvas());check(after.rgba!=image.rgba,"Closed popover still present on GPU");good(host.request_close());}}));
}
void lifetime(){
    gui::Host host;gui::Widget popup,field,anchor;int stale=0,closed=0;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.vstack({},"root"));anchor=take(w.button(root,"outside",{.text="Outside"},[&]{++stale;}));popup=take(w.popover(root,"popup",{}, {.closed=[&]{++closed;good(host.unmount_widgets());}}));auto content=take(w.vstack(popup,"content"));field=take(w.input_field(content,"field",{.commit_on_focus_loss=true},{},[]{}));return {};}));
        auto r=take(anchor.snapshot()).bounds;good(popup.open_at(200,150));good(m.dispatch_input({.kind=gui::WidgetInputKind::pointer_down,.x=r.x+2,.y=r.y+2}));check(closed==1&&stale==0&&!field.snapshot(),"Close callback leaked input into a retired generation");good(host.request_close());}}));
    gui::Host hiding;gui::Widget root;int late=0;
    good(hiding.run({.opened=[&]{auto m=take(hiding.mount_widgets([&](gui::WidgetBuilder&w)->core::Result<void>{root=take(w.vstack({},"root"));popup=take(w.popover(root,"popup",{}, {.closed=[&]{++late;}}));auto content=take(w.vstack(popup,"content"));field=take(w.input_field(content,"field",{.commit_on_focus_loss=true},{},[&]{good(hiding.unmount_widgets());}));return {};}));good(popup.open_at(50,50));good(root.set_visible(false));check(late==0&&!field.snapshot(),"Hiding a parent invoked popup callbacks after the blur callback retired its tree");good(hiding.request_close());}}));
}
void reentrant(){
    gui::Host host;gui::Widget popup,anchor;int closed=0,clicks=0;
    good(host.run({.opened=[&]{auto m=take(host.mount_widgets([&](gui::WidgetBuilder& w)->core::Result<void>{auto root=take(w.vstack({},"root"));anchor=take(w.button(root,"outside",{.text="Outside"},[&]{++clicks;}));popup=take(w.popover(root,"popup",{}, {.closed=[&]{if(++closed==1)good(popup.open_at(250,150));}}));auto content=take(w.vstack(popup,"content"));(void)take(w.input_field(content,"input"));return {};}));
        good(popup.open_at(200,150));click(m,take(anchor.snapshot()).bounds);check(closed==1&&clicks==0&&take(popup.snapshot()).opened,"Outside press reached an old target after a close callback reopened the popup");good(popup.close_popup());check(closed==2&&!take(popup.snapshot()).opened,"Reopened epoch did not retire independently");
        auto bad=host.mount_widgets([](gui::WidgetBuilder&w)->core::Result<void>{auto p=w.popover({},"bad");if(!p)return std::unexpected(p.error());auto a=w.label(*p,"a");if(!a)return std::unexpected(a.error());auto b=w.label(*p,"b");if(!b)return std::unexpected(b.error());return {};});check(!bad&&take(anchor.snapshot()).attached,"Invalid multi-content construction replaced the current tree");good(host.request_close());}}));
}
}
int main(int argc,char**argv){try{std::string name=argc>1?argv[1]:"lifecycle";if(name=="lifecycle")lifecycle();else if(name=="policies")policies();else if(name=="placement")placement();else if(name=="nesting")nesting();else if(name=="rendering")rendering();else if(name=="lifetime")lifetime();else if(name=="reentrant")reentrant();else throw std::runtime_error("Unknown popover test");std::cout<<"NATIVE_POPOVER_OK "<<name<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
